char arr[] = "ABCDE";
char *p = arr;
size_t offset = 2;

// Arithmetic respects base type (sizeof(char) = 1)
char *p_next = p + offset; // Points to 'C'

// Subtraction yields difference in elements (ptrdiff_t)
ptrdiff_t diff = p_next - p; // diff == 2

// Void pointer arithmetic (GCC/Clang extension)
void *v_p = arr;
void *v_p_next = v_p + 1; // v_p_next = arr + 1 byte

// Explicit casting for byte-wise arithmetic
int *i_p = (int*)arr;
char *byte_p = (char*)i_p;
byte_p += sizeof(int); // Moves 4 bytes
i_p = (int*)byte_p; // Points to next integer slot
